import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/commands.md","filePath":"modules/station/commands.md","lastUpdated":0}`),a={name:`modules/station/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiStation 的命令在运行时注册，不在 <code>paper-plugin.yml</code> 里声明 <code>commands:</code> 段。这与系列内其他模块一致。</p><p>主命令 <code>/emakistation</code>，别名 <code>/estation</code>、<code>/est</code>。不带参数或子命令无法识别时打印帮助。</p><h2 id="子命令" tabindex="-1">子命令 <a class="header-anchor" href="#子命令" aria-label="Permalink to “子命令”">​</a></h2><table tabindex="0"><thead><tr><th>用法</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/emakistation</code></td><td>无</td><td>打印帮助。</td></tr><tr><td><code>/emakistation open &lt;工作站&gt;</code></td><td><code>emakistation.use</code> + 该工作站访问权限</td><td>打开工作站界面。</td></tr><tr><td><code>/emakistation dismantle &lt;工作站&gt;</code></td><td><code>emakistation.dismantle</code> + 该分解站访问权限</td><td>打开分解界面。</td></tr><tr><td><code>/emakistation queue</code></td><td><code>emakistation.use</code></td><td>查看自己的队列。</td></tr><tr><td><code>/emakistation claim</code></td><td><code>emakistation.use</code></td><td>领取待领取的产物。</td></tr><tr><td><code>/emakistation cancel &lt;工作站&gt; &lt;序号&gt;</code></td><td><code>emakistation.use</code></td><td>取消队列条目。</td></tr><tr><td><code>/emakistation list [工作站]</code></td><td><code>emakistation.use</code></td><td>列出工作站，或列出某工作站的配方。</td></tr><tr><td><code>/emakistation reload</code></td><td><code>emakistation.reload</code></td><td>重载配置、工作站、配方与界面模板。</td></tr><tr><td><code>/emakistation debug</code></td><td><code>emakistation.debug</code></td><td>调试开关，参数与其他模块的 debug 子命令一致。</td></tr><tr><td><code>/emakistation admin queue &lt;玩家&gt;</code></td><td><code>emakistation.admin</code></td><td>查看指定玩家的队列，会异步加载离线玩家数据。玩家名必须在服务端缓存中，否则报未知玩家。</td></tr></tbody></table><p><code>open</code>、<code>cancel</code>、<code>list</code> 的第二个参数会补全为已加载的合成工作站 id；<code>dismantle</code> 补全为已加载的分解站 id。第一个参数的补全表还包含 <code>help</code>。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><p><code>paper-plugin.yml</code> 声明的权限及默认值：</p><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>emakistation.use</code></td><td><code>true</code></td><td>使用工作站界面与队列相关子命令。</td></tr><tr><td><code>emakistation.purchase</code></td><td><code>true</code></td><td>购买额外队列位。</td></tr><tr><td><code>emakistation.dismantle</code></td><td><code>true</code></td><td>使用分解界面。</td></tr><tr><td><code>emakistation.reload</code></td><td><code>op</code></td><td>重载配置。</td></tr><tr><td><code>emakistation.debug</code></td><td><code>op</code></td><td>调试开关。</td></tr><tr><td><code>emakistation.admin</code></td><td><code>op</code></td><td>管理员操作。</td></tr></tbody></table><p><code>emakistation.purchase</code> 刻意不放在 <code>emakistation.queue.*</code> 下面：那个前缀已经被队列长度分级占用，混在一起会让两种含义难以分辨。购买还需要 <code>config.yml</code> 的 <code>queue.purchase.enabled</code> 与工作站的 <code>queue.allow_purchase</code> 同时为 true。</p><h2 id="按工作站的访问权限" tabindex="-1">按工作站的访问权限 <a class="header-anchor" href="#按工作站的访问权限" aria-label="Permalink to “按工作站的访问权限”">​</a></h2><p>工作站与分解站各自有独立的访问权限前缀。配置里 <code>permission</code> 留空时回落到按 id 生成的节点：</p><table tabindex="0"><thead><tr><th>类型</th><th>配置键</th><th>留空时的回落节点</th></tr></thead><tbody><tr><td>合成工作站</td><td><code>stations/&lt;id&gt;.yml</code> 的 <code>permission</code></td><td><code>emakistation.access.&lt;id&gt;</code></td></tr><tr><td>分解站</td><td><code>stations_dismantle/&lt;id&gt;.yml</code> 的 <code>permission</code></td><td><code>emakistation.dismantle.access.&lt;id&gt;</code></td></tr></tbody></table><p>这两个前缀不在描述符里声明，因为节点名取决于管理员配了哪些工作站。给玩家开放示例工作站与示例分解站：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emakistation.access.blacksmith</span></span>
<span class="line"><span>emakistation.dismantle.access.example_dismantle</span></span></code></pre></div><h2 id="队列长度权限档" tabindex="-1">队列长度权限档 <a class="header-anchor" href="#队列长度权限档" aria-label="Permalink to “队列长度权限档”">​</a></h2><p>启用 <code>queue.permission_tiers</code> 后，<code>emakistation.queue.&lt;n&gt;</code> 中数字最大的一档生效，<code>&lt;n&gt;</code> 就是队列长度。没有任何该前缀权限时保持 <code>base_length</code> 不变。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emakistation.queue.8</span></span>
<span class="line"><span>emakistation.queue.16</span></span></code></pre></div><p>同时持有上面两个节点时生效的是 16。权限档<strong>取代</strong>基础长度，而付费队列位是<strong>叠加</strong>在生效档之上，最终统一被工作站的 <code>queue.max_length</code> 截断。</p><h2 id="线程说明" tabindex="-1">线程说明 <a class="header-anchor" href="#线程说明" aria-label="Permalink to “线程说明”">​</a></h2><p>任何触及玩家窗口或背包的子命令都会先切到该玩家的 owner 线程执行，因为命令可能来自控制台或另一个玩家的线程。在 Folia 上是实体调度器 owner，在 Paper 上是主服务器线程。</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};